package ec.edu.ucacue.odontocare.treatment.presentation;
import java.util.List;import org.springframework.http.HttpStatus;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import ec.edu.ucacue.odontocare.auth.application.UserPrincipal;import ec.edu.ucacue.odontocare.treatment.application.TreatmentService;import ec.edu.ucacue.odontocare.treatment.domain.TreatmentItemStatus;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.validation.Valid;
@RestController@RequestMapping("/api/clinical-records/{recordId}")@Tag(name="Tratamientos",description="Procedimientos, planes y evoluciones odontológicas")@SecurityRequirement(name="bearerAuth")public class TreatmentController{
 private final TreatmentService service;public TreatmentController(TreatmentService service){this.service=service;}
 @PostMapping("/consultations/{consultationId}/procedures")@ResponseStatus(HttpStatus.CREATED)@Operation(summary="Registrar procedimiento asociado a una consulta")public ProcedureResponse procedure(@PathVariable Long recordId,@PathVariable Long consultationId,@Valid @RequestBody ProcedureRequest request,@AuthenticationPrincipal UserPrincipal user){return service.createProcedure(recordId,consultationId,request,user);}
 @GetMapping("/procedures")@Operation(summary="Listar procedimientos de la HCE")public List<ProcedureResponse> procedures(@PathVariable Long recordId){return service.procedures(recordId);}
 @PostMapping("/treatment-plans")@ResponseStatus(HttpStatus.CREATED)@Operation(summary="Crear plan de tratamiento con ítems")public TreatmentPlanResponse plan(@PathVariable Long recordId,@Valid @RequestBody TreatmentPlanRequest request,@AuthenticationPrincipal UserPrincipal user){return service.createPlan(recordId,request,user);}
 @GetMapping("/treatment-plans")@Operation(summary="Listar planes e ítems")public List<TreatmentPlanResponse> plans(@PathVariable Long recordId){return service.plans(recordId);}
 @PatchMapping("/treatment-plans/{planId}/items/{itemId}/status")@Operation(summary="Actualizar estado sin eliminar historial")public TreatmentPlanResponse status(@PathVariable Long recordId,@PathVariable Long planId,@PathVariable Long itemId,@RequestParam TreatmentItemStatus value){return service.changeItemStatus(recordId,planId,itemId,value);}
 @PostMapping("/consultations/{consultationId}/clinical-evolutions")@ResponseStatus(HttpStatus.CREATED)@Operation(summary="Registrar evolución clínica")public EvolutionClinicalResponse evolution(@PathVariable Long recordId,@PathVariable Long consultationId,@Valid @RequestBody EvolutionClinicalRequest request,@AuthenticationPrincipal UserPrincipal user){return service.createEvolution(recordId,consultationId,request,user);}
 @GetMapping("/clinical-evolutions")@Operation(summary="Listar evoluciones de la HCE")public List<EvolutionClinicalResponse> evolutions(@PathVariable Long recordId){return service.evolutions(recordId);}
}
